using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using CelestialMaker.Core;
using BreakInfinity;
namespace CelestialMaker.EditorTools {
 public static partial class ObservatoryBatch {
  static void ReadabilityChecks(){
   Check("Research rows are compact and explain exact missing resource",()=>{Fixture(false,1,false,1920,1080);Set("page","Research");Call("ShowPc");Settle();Require(ui.GetComponentsInChildren<TMP_Text>().Any(t=>t.text.Contains("Need 190 more Energy")),"Missing resource reason");var rows=ui.GetComponentsInChildren<RectTransform>().Where(t=>t.name.StartsWith("Research row ")).ToArray();Require(rows.Length>1&&rows[0].rect.height<180,"Not a compact research row");Require(rows[1].GetComponentsInChildren<TMP_Text>().Any(t=>t.text.Contains("Research Quantum memory 1 first")),"Missing prerequisite reason");});
   Check("Research filter has selected fill and preserves independent upgrade choice",()=>{Fixture(false,1,false,1920,1080);Set("page","Research");Call("ShowPc");Click("Research filter 2");var chosen=Button("Research filter 2").GetComponent<CosmicPanel>();Require(chosen.edge==2&&chosen.color!=Button("Research filter 0").GetComponent<CosmicPanel>().color,"No selected appearance");Set("page","Upgrades");Call("ShowPc");Require(session.CurrentSettings.observatory.researchFilter==2&&session.CurrentSettings.observatory.upgradeFilter==0,"Filters coupled");});
   Check("Research search and favorite result filtering",()=>{Fixture(false,1,false,1920,1080);var p=session.CurrentSettings.observatory;p.researchSearch="Quantum memory 2";p.favorites.Add(GameSession.Content.research[1].id);p.researchFavorites=true;Set("page","Research");Call("ShowPc");Settle();Require(ui.GetComponentsInChildren<RectTransform>().Count(t=>t.name.StartsWith("Research row "))==1,"Search did not narrow list");p.researchSearch="no such research";Call("ShowPc");Require(Button("Clear research filters"),"No empty state recovery");Click("Clear research filters");Require(p.researchSearch==""&&!p.researchFavorites,"Clear filters incomplete");});
   Check("Search palette opens a route and persists favorites",()=>{Fixture(false,1,false,1920,1080);Call("SearchPalettePc",false);Set("pcPaletteQuery","Quantum memory 1");Call("PopulatePalettePc");Settle();Click("Add favorite");Require(session.CurrentSettings.observatory.favorites.Count==1,"Favorite not stored");Click("Research / Quantum memory 1");Require(Get<string>("page")=="Research"&&Get<string>("pcExpandedResearch")==GameSession.Content.research[0].id,"Search navigation failed");});
   Check("Pinned goal readiness notification is emitted once and can be disabled",()=>{Fixture(false,1,false,1920,1080);var p=session.CurrentSettings.observatory;p.goal=GameSession.Content.research[0].id;Set("pcGoalNotice","");Call("CheckPinnedGoalPc");session.Sim.S.resources[0]=new BigDouble(1000);Call("CheckPinnedGoalPc");Require(Get<string>("pcToastText").StartsWith("Goal ready"),"No readiness notice");Set("pcToastText","sentinel");Call("CheckPinnedGoalPc");Require(Get<string>("pcToastText")=="sentinel","Repeated notice");p.readyNotifications=false;session.Sim.Purchase(GameSession.Content.research[0]);Call("CheckPinnedGoalPc");Require(Get<string>("pcToastText")=="sentinel","Disabled notifications emitted");});
   Check("Category labels and all button states keep readable contrast",()=>{foreach(bool light in new[]{false,true}){Fixture(true,1,light,1920,1080);var colors=new HashSet<Color>();foreach(var b in Get<Dictionary<string,Button>>("pcTabs").Values){colors.Add(b.GetComponentInChildren<ObservatoryCategoryIcon>().color);foreach(string state in new[]{"Normal","Highlighted","Selected","Disabled"}){ButtonState((ObservatoryButton)b,state);float a=Luminance(b.GetComponentInChildren<TMP_Text>().color),bg=Luminance(b.GetComponent<CosmicPanel>().color);Require((Mathf.Max(a,bg)+.05f)/(Mathf.Min(a,bg)+.05f)>=4.5f,"Contrast failed");}}Require(colors.Count==6,"Category accents not distinct");}});
   Check("Preferences and queue survive Unity JSON and old save defaults",()=>{Fixture(false,1,false,1920,1080);session.Sim.QueueResearch(GameSession.Content.research[1].id);session.CurrentSettings.observatory.favorites.Add("page:Research");session.CurrentSettings.observatory.researchFilter=2;var state=SaveStore.Parse(JsonUtility.ToJson(session.Sim.S));Require(state.researchPlan.queue.Count==2&&state.settings.observatory.researchFilter==2&&state.settings.observatory.favorites.Contains("page:Research"),"Unity lost planning fields");var old=new State{researchPlan=null};old.settings.observatory=null;var migrated=SaveStore.Parse(JsonUtility.ToJson(old));Require(migrated.researchPlan!=null&&migrated.settings.observatory!=null,"Old optional fields not migrated");});
   foreach(float scale in new[]{1f,2f})foreach(bool light in new[]{false,true}){
    string key=scale+"/"+light;
    Check("Expanded research and pinned goal geometry "+key,()=>{Fixture(false,scale,light,1280,720);session.Sim.S.resources[0]=new BigDouble(10000);session.CurrentSettings.observatory.goal=GameSession.Content.research[0].id;Set("page","Research");Set("pcExpandedResearch",GameSession.Content.research[0].id);Call("ShowPc");Settle();Geometry("expanded research");});
    Check("Search plan comparison and navigation dialogs geometry "+key,()=>{Fixture(false,scale,light,1280,720);session.Sim.S.resources[0]=new BigDouble(10000);session.Sim.QueueResearch(GameSession.Content.research[1].id);Call("ResearchPlanPc");Settle();Geometry("plan");Call("ClosePcModal");Call("SearchPalettePc",false);Settle();Geometry("search");Call("ClosePcModal");Call("ResearchFilterDialogPc",true);Settle();Geometry("compact filters");var query=Get<RectTransform>("pcModal").GetComponentInChildren<TMP_InputField>();query.text="Quantum";Click("Cancel");Require(session.CurrentSettings.observatory.researchSearch=="","Cancelled filters leaked");Call("SectionViewsPc");Settle();Geometry("compact views");Call("ClosePcModal");Call("ResearchComparisonPc",GameSession.Content.research[0]);Settle();Geometry("comparison");Call("ClosePcModal");Call("NavigationDrawerPc");Settle();Geometry("drawer");Require(!Button("Development")&&Button("Production"),"Locked navigation leaked");Click("Production");Require(Get<string>("page")=="Production","Drawer selection failed");});
   }
   Check("Narrow window expands workspace and hides side panels",()=>{Fixture(false,1,false,960,720);Require(Get<bool>("pcCompactNav")&&Get<RectTransform>("pcInspector")==null&&Button("Menu / Find"),"Adaptive navigation missing");Require(Get<RectTransform>("body").rect.width>900,"Workspace still reserves rail");Set("page","Research");Call("ShowPc");Settle();Geometry("960 wide");});
  }
 }
}
